parameters.query:
[
  {
    "$match": {
      "updatedAt": {
        "$gte": { "$dateSubtract": { "startDate": "$$NOW", "unit": "hour", "amount": 1 } }
      },
      "role": "user"
    }
  },
  {
    "$addFields": {
      "milestones": {
        "$filter": {
          "input": [
            { "$cond": [{ "$and": [{ "$eq": ["$progress.completedLessons", 1] }] }, { "type": "first_lesson", "label": "First Lesson Completed", "labelAr": " " }, null] },
            { "$cond": [{ "$and": [{ "$gte": ["$progress.completedLessons", 10] }, { "$lt": ["$progress.completedLessons", 11] }] }, { "type": "10_lessons", "label": "10 Lessons Completed", "labelAr": "10  " }, null] },
            { "$cond": [{ "$and": [{ "$gte": ["$progress.completedLessons", 50] }, { "$lt": ["$progress.completedLessons", 51] }] }, { "type": "50_lessons", "label": "50 Lessons Completed", "labelAr": "50  " }, null] },
            { "$cond": [{ "$and": [{ "$gte": ["$progress.completedLessons", 100] }, { "$lt": ["$progress.completedLessons", 101] }] }, { "type": "100_lessons", "label": "100 Lessons Completed", "labelAr": "100  " }, null] },
            { "$cond": [{ "$gte": ["$contributionCount.count", 1] }, { "type": "first_contribution", "label": "First Contribution", "labelAr": " " }, null] }
          ],
          "as": "m",
          "cond": { "$ne": ["$$m", null] }
        }
      }
    }
  },
  {
    "$match": {
      "milestones": { "$ne": [] }
    }
  },
  {
    "$project": {
      "_id": 1,
      "displayName": 1,
      "email": 1,
      "milestones": 1,
      "progress.completedLessons": 1,
      "progress.learningTime": 1,
      "contributionCount": 1,
      "progress.timeSpentHistory": 1
    }
  }
]

parameters.jsCode:
const users = $input.all();
const results = [];

for (const user of users) {
  const u = user.json;
  const milestones = [];

  // Lesson milestones
  const lessons = u.progress?.completedLessons || 0;
  if (lessons === 1) milestones.push({ type: 'first_lesson', labelAr: ' ', significant: false });
  if (lessons >= 10 && lessons < 12) milestones.push({ type: '10_lessons', labelAr: '10  ', significant: false });
  if (lessons >= 50 && lessons < 52) milestones.push({ type: '50_lessons', labelAr: '50  ', significant: true });
  if (lessons >= 100 && lessons < 102) milestones.push({ type: '100_lessons', labelAr: '100  !', significant: true });

  // Streak milestones (check timeSpentHistory for consecutive days)
  const history = u.progress?.timeSpentHistory || [];
  if (history.length >= 7) {
    const last7 = history.slice(-7);
    const has7DayStreak = last7.every(d => d.minutes > 0);
    if (has7DayStreak) milestones.push({ type: '7_day_streak', labelAr: '  7 !', significant: false });
  }
  if (history.length >= 30) {
    const last30 = history.slice(-30);
    const has30DayStreak = last30.every(d => d.minutes > 0);
    if (has30DayStreak) milestones.push({ type: '30_day_streak', labelAr: '  30 !', significant: true });
  }

  // Contribution milestones
  const contribCount = u.contributionCount?.count || 0;
  if (contribCount === 1) milestones.push({ type: 'first_contribution', labelAr: ' !', significant: false });
  if (contribCount >= 10) milestones.push({ type: 'top_contributor', labelAr: '  !', significant: true });

  if (milestones.length > 0) {
    results.push({
      json: {
        ...u,
        detectedMilestones: milestones,
        hasSignificantMilestone: milestones.some(m => m.significant)
      }
    });
  }
}

return results;

