const item = $input.first().json;
const aiContent = item.text || item.message?.content || '';
const userData = $('Detect Milestone Types').first().json;
const milestoneLabels = userData.detectedMilestones.map(m => m.labelAr).join(' | ');

const html = `<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head><meta charset="UTF-8"><style>
body { font-family: 'Segoe UI', Tahoma, sans-serif; background: #f4f6f9; margin: 0; padding: 0; direction: rtl; }
.container { max-width: 600px; margin: 20px auto; background: #fff; border-radius: 12px; overflow: hidden; box-shadow: 0 2px 12px rgba(0,0,0,.08); }
.header { background: linear-gradient(135deg, #f39c12, #e67e22, #e74c3c); padding: 50px 30px; text-align: center; color: #fff; }
.header h1 { margin: 0; font-size: 32px; text-shadow: 0 2px 4px rgba(0,0,0,.2); }
.header .milestone-badge { display: inline-block; background: rgba(255,255,255,.2); padding: 8px 20px; border-radius: 24px; margin-top: 12px; font-size: 16px; }
.body { padding: 30px; color: #444; line-height: 1.8; }
.achievement-card { background: linear-gradient(135deg, #fff9e6, #fffbe6); border: 2px solid #f39c12; border-radius: 12px; padding: 20px; text-align: center; margin: 20px 0; }
.achievement-card .icon { font-size: 48px; }
.achievement-card .title { font-size: 20px; font-weight: 700; color: #e67e22; margin: 8px 0; }
.cta { display: block; width: fit-content; margin: 24px auto; padding: 14px 40px; background: linear-gradient(135deg, #f39c12, #e67e22); color: #fff; text-decoration: none; border-radius: 8px; font-size: 16px; font-weight: 600; }
.footer { text-align: center; padding: 20px; color: #999; font-size: 12px; border-top: 1px solid #eee; }
</style></head>
<body><div class="container">
  <div class="header">
    <h1>   !</h1>
    <div class="milestone-badge">${milestoneLabels}</div>
  </div>
  <div class="body">
    <div class="achievement-card">
      <div class="icon">&#127942;</div>
      <div class="title">${milestoneLabels}</div>
    </div>
    ${aiContent}
    <a href="https://udarsy.dz/explore" class="cta">  </a>
  </div>
  <div class="footer">
    <p>Udarsy - </p>
  </div>
</div></body></html>`;

return [{ json: { ...userData, htmlEmail: html } }];

